package com.lqq.supportflow.knowledge.application;
import com.lqq.supportflow.knowledge.domain.*; import com.lqq.supportflow.model.ModelEmbeddingService; import java.util.*; import org.springframework.stereotype.Service;
@Service public class RebuildKnowledgeIndexService { private final KnowledgeDocumentPort documents; private final KnowledgeChunkPort chunks; private final ModelEmbeddingService embeddings; private final KnowledgeSearchIndex index; public RebuildKnowledgeIndexService(KnowledgeDocumentPort documents,KnowledgeChunkPort chunks,ModelEmbeddingService embeddings,KnowledgeSearchIndex index){this.documents=documents;this.chunks=chunks;this.embeddings=embeddings;this.index=index;} public int rebuild(Long tenantId,Long knowledgeBaseId){int count=0;for(KnowledgeDocument document:documents.findByKnowledgeBase(tenantId,knowledgeBaseId)){if(document.status()!=IngestionStatus.INDEXED)continue;List<KnowledgeChunk> source=chunks.findByDocument(tenantId,knowledgeBaseId,document.id());if(source.isEmpty())continue;List<float[]> vectors=embeddings.embed(tenantId,source.stream().map(KnowledgeChunk::content).toList());List<IndexedKnowledgeChunk> entries=new ArrayList<>();for(int position=0;position<source.size();position++)entries.add(new IndexedKnowledgeChunk(source.get(position),vectors.get(position)));index.index(tenantId,knowledgeBaseId,document.id(),entries);count+=entries.size();}return count;}}
